/**
 * @file vmap_route_trip.c
 * @brief vmap route_trip 模块。
 */

#include "vmap_route_trip.h"

#include "vmap_geo.h"
#include "vmap_map_catalog.h"
#include "vmap_route_log.h"
#include "vmap_route_portal.h"
#include <string.h>

/**
 * @brief 重置行程状态。
 * @param trip 行程。
 */
void vmap_route_trip_reset(vmap_route_trip_t * trip)
{
    if (trip) {
        memset(trip, 0, sizeof(*trip));
    }
}

/**
 * @brief 设置途经点列表。
 * @return true 成功/有效，false 失败/无效。
 */
bool vmap_route_trip_set_waypoints(vmap_route_trip_t * trip,
    const vmap_route_waypoint_t * wps, uint32_t count)
{
    if (!trip || !wps || count == 0 || count > VMAP_ROUTE_TRIP_MAX_WAYPOINTS) {
        return false;
    }

    memcpy(trip->wps, wps, (size_t)count * sizeof(trip->wps[0]));
    trip->wp_count = count;
    trip->leg_idx = 0;
    trip->region_path_len = 0;
    trip->region_refined = 0;
    trip->active = true;
    return true;
}

/**
 * @brief 当前 leg 终点。
 */
bool vmap_route_trip_leg_target(const vmap_route_trip_t * trip,
    double * lon, double * lat)
{
    return vmap_route_trip_waypoint_at(trip, trip ? trip->leg_idx : 0u, lon, lat)
        && trip && trip->active;
}

bool vmap_route_trip_waypoint_at(const vmap_route_trip_t * trip, uint32_t idx,
    double * lon, double * lat)
{
    if (!trip || idx >= trip->wp_count || !lon || !lat) {
        return false;
    }

    *lon = trip->wps[idx].lon;
    *lat = trip->wps[idx].lat;
    return true;
}

bool vmap_route_trip_fill_path(const char * map_dir, double from_lon,
    double from_lat, double to_lon, double to_lat, vmap_cell_id_t * path,
    uint32_t cap, uint32_t * out_len)
{
    vmap_cell_id_t start_rid;
    vmap_cell_id_t dest_rid;

    if (!map_dir || !path || cap == 0u || !out_len) {
        return false;
    }

    if (!vmap_map_catalog_load(map_dir) || !vmap_map_catalog_is_regional()) {
        VMAP_NAV_WARN("trip: catalog not regional");
        return false;
    }

    (void)vmap_route_portal_load(map_dir);

    if (!vmap_map_catalog_find_region(from_lon, from_lat, &start_rid)
        || !vmap_map_catalog_find_region(to_lon, to_lat, &dest_rid)) {
        VMAP_NAV_WARN("trip: leg outside catalog");
        return false;
    }

    if (start_rid == dest_rid) {
        path[0] = start_rid;
        *out_len = 1u;
        return true;
    }

    if (!vmap_map_catalog_region_path(start_rid, dest_rid, path, cap, out_len)) {
        VMAP_NAV_WARN("trip: no region path r%u->r%u",
            (unsigned)start_rid, (unsigned)dest_rid);
        return false;
    }
    return true;
}

/**
 * @brief 开始当前 leg 规划。
 * @return true 成功/有效，false 失败/无效。
 */
bool vmap_route_trip_begin_leg(const char * map_dir, vmap_route_trip_t * trip,
    double from_lon, double from_lat)
{
    double to_lon;
    double to_lat;

    if (!map_dir || !trip || !trip->active || trip->leg_idx >= trip->wp_count) {
        return false;
    }

    to_lon = trip->wps[trip->leg_idx].lon;
    to_lat = trip->wps[trip->leg_idx].lat;
    trip->region_path_len = 0;
    trip->region_refined = 0;

    if (!vmap_route_trip_fill_path(map_dir, from_lon, from_lat, to_lon, to_lat,
            trip->region_path, VMAP_ROUTE_REGION_PATH_MAX,
            &trip->region_path_len)) {
        return false;
    }

    VMAP_NAV_OUT("trip: two-point leg %u/%u region_path len=%u",
        (unsigned)(trip->leg_idx + 1u), (unsigned)trip->wp_count,
        trip->region_path_len);
    return true;
}

/**
 * @brief 进入下一 leg。
 * @return true 成功/有效，false 失败/无效。
 */
bool vmap_route_trip_advance_leg(vmap_route_trip_t * trip)

    map_page_nav_gnss_for_sim(page);
    map_page_gpx_course_clear(page);

    return map_page_nav_plan_begin(page, from_lon, from_lat, to_lon, to_lat, true,
        false);
}

/**
 * @brief 多途经点规划：当前坐标不算，一次规划下一点与下下一点。
 */
bool map_page_nav_trip_plan(map_page_t * page,
    const vmap_route_waypoint_t * waypoints, uint32_t count)
{
    bicycle_gnss_fix_t fix;
    bool mtp_was_held;
    bool top_was_only;

    if (!page || !waypoints || count == 0) {
        return false;
    }
    memset(page->nav_trip_names, 0, sizeof(page->nav_trip_names));
    page->nav_trip_name_count = 0u;
    if (page->nav_planning) {
        return false;
    }
    top_was_only = page->nav_top_only;
    page->nav_top_only = true;
    mtp_was_held = page->nav_mtp_held;
    if (!map_page_nav_mtp_acquire(page)) {
        page->nav_top_only = top_was_only;
        return false;
    }
    if (!map_page_ensure_route_nav(page)) {
        page->nav_top_only = top_was_only;
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }
    if (!bicycle_runtime_poll_fix(&fix) || !fix.valid) {
        fix.longitude = (float)waypoints[0].lon;
        fix.latitude = (float)waypoints[0].lat;
        fix.valid = true;
        VMAP_NAV_WARN("nav_trip: no GNSS, start at first waypoint");
    }
    if (myvendor_mtp_lfs_quiesce()) {
        page->nav_top_only = top_was_only;
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }

    vmap_route_worker_init();
    if (vmap_route_worker_busy()) {
        page->nav_top_only = top_was_only;
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }
    map_page_gpx_rejoin_reset(page);
    vmap_route_worker_cancel();
    vmap_route_nav_stop(page->nav);
    vmap_route_trip_reset(&page->nav_trip);
    map_page_gpx_course_clear(page);
    map_page_trip_ahead_clear(page);
    if (!vmap_route_trip_set_waypoints(&page->nav_trip, waypoints, count)) {
        page->nav_top_only = top_was_only;
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }

    /* 站在某站上＝那一站已经过掉（trip 的语义本来就是「当前坐标不算」）：
     * 把已经在脚下的前置站跳掉，从第一个真正没到的站开始规划。
     *
     * 不跳的话这段 leg 长度 ~0，`vmap_route_compute()` 会以 "already at dest"
     * 拒绝，用户看到的就是「已在终点附近」—— 哪怕后面还有好几站没去。
     * 返回 false 表示连最后一站也在脚下，那才是真的没什么可导的。
     *
     * 顺带把上面「无定位时把起点当成第 1 个站」那条兜底也接上了：那种情况下
     * `skip_reached()` 会跳过 wps[0]，leg 正好从第 2 个站起算，与那句
     * "start at first waypoint" 的注释一致（在此之前它实际会去规划一条
     * 起点＝终点的 0 长度 leg，必然失败）。 */
    if (!vmap_route_trip_skip_reached(&page->nav_trip, fix.longitude,
            fix.latitude)) {
        vmap_route_trip_reset(&page->nav_trip);
        page->nav_top_only = top_was_only;
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }

    page->nav_trip_active = true;
    page->nav_gpx_course = false;
    page->nav_user_set = true;
    page->nav_planned = false;
    page->nav_replanning = false;
    page->nav_reroute_reason = VMAP_ROUTE_REROUTE_NONE;
    page->nav_last_reroute_ms = 0u;
    page->nav_last_reroute_lon = 0.0;
    page->nav_last_reroute_lat = 0.0;
    page->nav_off_since_ms = 0u;
    /* 用户是从菜单里点的导航，此刻地图还盖在菜单下面，refresh_map 会早退；
     * 这里先把剩余航点挂上，菜单一收起就是对的。 */
    map_page_trip_pins_sync(page);

    /* 当前坐标不算：规划 GPS→当前站，并在完成后静默预规划下一站。
     * 起始站可能不是第 1 个（前面几站人已经站在上面了，见上面的 skip）。 */
    VMAP_NAV_LOG("nav_trip: %u waypoints, start leg %u/%u", (unsigned)count,
        (unsigned)(vmap_route_trip_leg_index(&page->nav_trip) + 1u),
        (unsigned)count);
    map_page_plan_hint_show(page, "加载路网");
    if (!vmap_route_trip_begin_leg(VMAP_TILE_DIR, &page->nav_trip,
            fix.longitude, fix.latitude)) {
        page->nav_trip_active = false;
        page->nav_top_only = top_was_only;
        vmap_route_trip_reset(&page->nav_trip);
        map_page_plan_hint_hide(page);
        if (!mtp_was_held) {
            map_page_nav_mtp_release(page);
        }
        return false;
    }

    if (map_page_nav_rolling_begin(page, fix.longitude, fix.latitude, false,
            false)) {
        helm_shell_on_nav_started();
        return true;
    }

    map_page_plan_hint_hide(page);
    page->nav_top_only = top_was_only;
    if (!mtp_was_held) {
        map_page_nav_mtp_release(page);
    }
    return false;
}

void map_page_nav_trip_set_names(map_page_t * page,
    const char * const * names, uint32_t count)
{
    uint32_t i;

    if (!page) {
        return;
    }
    memset(page->nav_trip_names, 0, sizeof(page->nav_trip_names));
    page->nav_trip_name_count = 0u;
    if (!names) {
        return;
    }
    if (count > VMAP_ROUTE_TRIP_MAX_WAYPOINTS) {
        count = VMAP_ROUTE_TRIP_MAX_WAYPOINTS;
    }
    for (i = 0u; i < count; i++) {
        if (names[i] != NULL) {
            lv_snprintf(page->nav_trip_names[i],
                sizeof(page->nav_trip_names[i]), "%s", names[i]);
        }
    }
    page->nav_trip_name_count = (uint8_t)count;
}

/**
 * @brief 停止导航并清路线叠层。
