/**
 * @brief 自行车 runtime update sensors。
 */
void bicycle_runtime_update_sensors(uint16_t hr_bpm, bool hr_valid,
    uint16_t cadence_rpm, bool cadence_valid, uint16_t power_w,
    bool power_valid)
{
    g_rt.hr_bpm = hr_bpm;
    g_rt.hr_valid = hr_valid;
    g_rt.cadence_rpm = cadence_rpm;
    g_rt.cadence_valid = cadence_valid;
    g_rt.power_w = power_w;
    g_rt.power_valid = power_valid;
    if (g_rt.recording && hr_valid && hr_bpm > 0u) {
        uint32_t now = lv_tick_get();

        if (g_hr_last_ms == 0u || (now - g_hr_last_ms) >= 1000u) {
            g_hr_sum += hr_bpm;
            g_hr_n++;
            g_rt.hr_avg_bpm = (uint16_t)((g_hr_sum + g_hr_n / 2u) / g_hr_n);
            if (hr_bpm > g_rt.hr_max_bpm) {
                g_rt.hr_max_bpm = hr_bpm;
            }

            g_hr_last_ms = now;
        }
    }

    bicycle_runtime_ui_sync();
}

/**
 * @brief 自行车 runtime add segment。
 */
void bicycle_runtime_add_segment(double seg_m, float motion_deg, float speed_kph)
{
    uint32_t now;
    float dt_s;
    double max_m;

    if (seg_m <= 0.0) {
        return;
    }

    now = lv_tick_get();

    if (page->nav_gpx_pts && page->nav_gpx_n >= 2u && poly_m > 0.0) {
        if (page->nav_gpx_dense) {
            r = poly_m - (page->nav_gpx_win_start_m + st->along_m);
        } else if (page->nav_gpx_sparse) {
            r = (poly_m - page->nav_gpx_win_end_m) + st->remain_m;
        }
        if (r < 0.0) {
            r = 0.0;
        } else if (r > poly_m) {
            r = poly_m;
        }
        if (page->nav_gpx_true_m > poly_m && poly_m > 1.0) {
            r = page->nav_gpx_true_m * (r / poly_m);
        }
    }
    return r;
}

/**
 * @brief 把行程剩余航点交给路线叠层（地图上画成小圆点）。
 *
 * 放在导航几何刷新路径上：那里正好是 canvas 要重盖的时刻，点位和线不会错拍。
 * 但被菜单盖住时 `map_page_nav_refresh_map()` 会早退，所以行程起步时也直接叫一次
 * （用户就是从菜单里点的导航）。
 */
static void map_page_trip_pins_sync(map_page_t * page)
{
    if (!page || !page->route) {
        return;
    }

    if (!page->nav_trip_active) {
        vmap_route_set_trip_pins(page->route, NULL, 0u, 0u);
        return;
    }

    vmap_route_set_trip_pins(page->route, page->nav_trip.wps,
        page->nav_trip.wp_count,
        vmap_route_trip_leg_index(&page->nav_trip));
}

static void map_page_trip_ahead_clear(map_page_t * page)
{
